create index if not exists documents_investor_id_idx on public.documents (investor_id);
create index if not exists documents_opportunity_id_idx on public.documents (opportunity_id);
create trigger documents_touch before update on public.documents for each row execute function public.touch_updated_at();

create table if not exists public.ai_recommendations (
  id uuid primary key default gen_random_uuid(),
  organisation_id uuid not null references public.organisations(id) on delete cascade,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  created_by uuid,
  title text not null,
  kind text check (kind in ('proposed_change', 'insight')),
  target_table text,
  status text check (status in ('pending', 'approved', 'rejected', 'applied')),
  rationale text,
  confidence text check (confidence in ('low', 'medium', 'high')),
  target_id uuid,
  action text not null default 'create' check (action in ('create','update')),
  payload jsonb not null default '{}'::jsonb,
  source_refs jsonb not null default '[]'::jsonb,
  decided_by text,
  decided_at timestamptz,
  applied_record_id uuid,
  rejection_reason text,
  meeting_id uuid references public.meetings(id) on delete set null,
  meeting_action_id uuid references public.meeting_actions(id) on delete set null
);
